from typing import Any, Dict, Iterable, List, Mapping, Optional, Sequence, Set, Tuple, Union
from stockflow.parse_movement_line import parse_movement_line


def dead_stock(lines: Iterable[str], case_sizes: Mapping[str, int], today: int, idle_days: int) -> List[str]:
    if idle_days < 1:
        raise ValueError("idle_days must be >= 1")

    on_hand: Dict[str, int] = {}
    last_ship_day: Dict[str, int] = {}
    first_movement_day: Dict[str, int] = {}

    for line in lines:
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            continue

        move = parse_movement_line(stripped, case_sizes)
        day = move["day"]
        if day > today:
            continue

        sku = move["sku"]
        qty = move["qty"]
        mtype = move["type"]

        on_hand[sku] = on_hand.get(sku, 0) + qty
        if sku not in first_movement_day:
            first_movement_day[sku] = day
        if mtype == "SHP":
            last_ship_day[sku] = day

    dead_skus = []
    for sku, qty in on_hand.items():
        if qty > 0:
            if sku in last_ship_day:
                if today - last_ship_day[sku] >= idle_days:
                    dead_skus.append(sku)
            elif sku in first_movement_day:
                if today - first_movement_day[sku] >= idle_days:
                    dead_skus.append(sku)

    return sorted(dead_skus)"}}}
