from typing import Dict, Iterable, List, Mapping, Set, Tuple

from .on_hand_by_location import on_hand_by_location
from .normalize_sku import normalize_sku
from .parse_location import parse_location


def _format_location(loc_tuple: Tuple[str, int, int, int]) -> str:
    zone, aisle, shelf, level = loc_tuple
    return f"{zone}-{aisle:02d}-{shelf:02d}-{level}"


def cycle_count_variance(lines: Iterable[str], case_sizes: Mapping[str, int], counts: Mapping[Tuple[str, str], int]) -> List[Tuple[str, str, int]]:
    normalized_counts: Dict[Tuple[str, str], int] = {}
    for (sku_raw, loc_raw), qty in counts.items():
        if qty < 0:
            raise ValueError(f"Counted quantity cannot be negative: {qty}")
        sku = normalize_sku(sku_raw)
        loc_tuple = parse_location(loc_raw)
        loc = _format_location(loc_tuple)
        key = (sku, loc)
        normalized_counts[key] = normalized_counts.get(key, 0) + qty

    system_stock = on_hand_by_location(lines, case_sizes)

    counted_locations: Set[str] = set()
    for (sku, loc) in normalized_counts.keys():
        counted_locations.add(loc)

    variances: List[Tuple[str, str, int]] = []

    for loc in counted_locations:
        skus_in_counts = {sku for (sku, l) in normalized_counts.keys() if l == loc}
        skus_in_system = {sku for (sku, l) in system_stock.keys() if l == loc}
        all_skus = skus_in_counts | skus_in_system

        for sku in all_skus:
            counted_qty = normalized_counts.get((sku, loc), 0)
            system_qty = system_stock.get((sku, loc), 0)
            variance = counted_qty - system_qty

            if variance != 0:
                variances.append((sku, loc, variance))

    variances.sort(key=lambda x: (x[1], x[0]))
    return variances
"}}, "messages": []}

