from typing import Dict, List, Sequence, Tuple

def split_shipment(lines: Sequence[Tuple[str, int, int]], max_parcel_grams: int) -> List[Dict[str, int]]:
    if max_parcel_grams <= 0:
        raise ValueError("max_parcel_grams must be positive")
    sku_data: Dict[str, Tuple[int, int]] = {}
    for sku, qty, unit_weight in lines:
        if qty <= 0:
            raise ValueError(f"qty must be positive, got {qty}")
        if unit_weight <= 0:
            raise ValueError(f"unit_weight must be positive, got {unit_weight}")
        if unit_weight > max_parcel_grams:
            raise ValueError(f"unit weight exceeds max: {unit_weight}")
        if sku in sku_data:
            eq, ew = sku_data[sku]
            if ew != unit_weight:
                raise ValueError(f"SKU {sku} has conflicting weights")
            sku_data[sku] = (eq + qty, unit_weight)
        else:
            sku_data[sku] = (qty, unit_weight)
    # Sort by unit_weight desc, then sku for stability (FFD on units)
    sorted_skus = sorted(sku_data.keys(), key=lambda s: (-sku_data[s][1], s))
    parcels: List[Dict[str, int]] = []
    parcel_weights: List[int] = []
    for sku in sorted_skus:
        qty, unit_weight = sku_data[sku]
        remaining = qty
        while remaining > 0:
            placed = False
            for i, pw in enumerate(parcel_weights):
                if pw + unit_weight <= max_parcel_grams and (sku not in parcels[i] or True):
                    # Try to add one unit to existing parcel
                    if pw + unit_weight <= max_parcel_grams:
                        parcels[i][sku] = parcels[i].get(sku, 0) + 1
                        parcel_weights[i] = pw + unit_weight
                        remaining -= 1
                        placed = True
                        break
            if not placed:
                # Start new parcel with as many units as fit
                take = min(max_parcel_grams // unit_weight, remaining)
                parcels.append({sku: take})
                parcel_weights.append(take * unit_weight)
                remaining -= take
    return parcels
"}}, "messages": []}

